import{_ as o,o as r,c as t,ag as i}from"./chunks/framework.cyF4XceO.js";const u=JSON.parse('{"title":"Provider v3 to v4 publisher-set boundary","description":"","frontmatter":{},"headers":[],"relativePath":"release/migrations/v3-to-v4.md","filePath":"release/migrations/v3-to-v4.md"}'),a={name:"release/migrations/v3-to-v4.md"};function n(s,e,d,c,l,p){return r(),t("div",null,[...e[0]||(e[0]=[i('<h1 id="provider-v3-to-v4-publisher-set-boundary" tabindex="-1">Provider v3 to v4 publisher-set boundary <a class="header-anchor" href="#provider-v3-to-v4-publisher-set-boundary" aria-label="Permalink to &quot;Provider v3 to v4 publisher-set boundary&quot;">​</a></h1><p>Provider <code>3.0.0</code> is immutable Registry history for a 31-resource aggregate. Provider <code>4.0.0</code> at the same <code>registry.terraform.io/tako0614/takoform</code> source address registers only the 17 exact Forms selected from the <code>github.com/tako0614/takoform-forms</code> publisher in the <code>edge.forms.takoform.com</code> family. It is a candidate descriptor until an immutable Registry readback records publication.</p><h2 id="_15-withdrawn-aggregate-resource-types" tabindex="-1">15 withdrawn aggregate resource types <a class="header-anchor" href="#_15-withdrawn-aggregate-resource-types" aria-label="Permalink to &quot;15 withdrawn aggregate resource types&quot;">​</a></h2><p>The following Provider 3 resource types are not part of the publisher-selected Provider roster:</p><ul><li><code>takoform_container_custom_domain</code></li><li><code>takoform_container_endpoint</code></li><li><code>takoform_container_revision</code></li><li><code>takoform_container_traffic</code></li><li><code>takoform_serverless_container_service</code></li><li><code>takoform_function</code></li><li><code>takoform_function_deployment</code></li><li><code>takoform_function_endpoint</code></li><li><code>takoform_function_version</code></li><li><code>takoform_pull_queue</code></li><li><code>takoform_message_schedule</code></li><li><code>takoform_table</code></li><li><code>takoform_topic</code></li><li><code>takoform_topic_subscription</code></li><li><code>takoform_dense_vector_index</code></li></ul><p>Their Provider 3 FormRef, codec, package, release, and Registry evidence remains immutable history. They are not renamed, reoccupied, or described as current publisher-selected Forms.</p><h2 id="state-transition" tabindex="-1">State transition <a class="header-anchor" href="#state-transition" aria-label="Permalink to &quot;State transition&quot;">​</a></h2><p>An operator with any removed resource type in state must choose explicitly before upgrading:</p><ol><li>Keep <code>version = &quot;= 3.0.0&quot;</code> and continue using the retained Provider binary.</li><li>Destroy the remote object while pinned to Provider 3, then remove the old configuration.</li><li>Use <code>tofu state rm</code> only when intentionally leaving the remote object unmanaged.</li><li>Create or import the replacement with its owning OpenTofu provider, verify it, then remove the old Provider 3 state entry.</li></ol><p>Do not use <code>tofu state replace-provider</code> to turn a removed Takoform resource into an AWS, Cloudflare, Kubernetes, or other provider resource. Provider addresses, resource types, schemas, identities, and lifecycle semantics differ; blind replacement would ask a different provider to decode incompatible state.</p><p>Upgrading with a removed resource still in configuration or state fails before Takoform lifecycle mutation because the next major does not register its type.</p><h2 id="native-provider-composition" tabindex="-1">Native provider composition <a class="header-anchor" href="#native-provider-composition" aria-label="Permalink to &quot;Native provider composition&quot;">​</a></h2><p>Industry-standard and provider-native resources stay with their owning providers. A module may declare <code>takoform</code> together with AWS, Cloudflare, Kubernetes, PostgreSQL, or any other runner-installable provider. OpenTofu owns provider installation, aliases, graph edges, plan/state, and dependency order. Takoform neither wraps those resources as Forms nor acts as a provider catalog.</p><p>The repository includes an <a href="../../examples/native-provider-composition/main.tf">AWS plus Takoform example</a>.</p>',14)])])}const h=o(a,[["render",n]]);export{u as __pageData,h as default};
